import {ContractError} from './cloud-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {payrollCents,payrollMoney} from './payroll-contract.mjs';
export function createPayrollEditors({api,h,mount,input,area}){
 return {async payrollEdit(month,memberId,salaries=false){
  if(!hasSensitive(await api.session(),'payroll'))throw new ContractError('需要独立薪资授权。');const s=await api.payrollState(month,memberId);if(!s.member)throw new ContractError('员工档案不存在。');const key=crypto.randomUUID(),amount=(name,label,c)=>input(name,label,(c/100).toFixed(2),'required inputmode="decimal"');
  if(salaries){const history=await api.payrollHistory(month,memberId,0,true),last=history.rows[0];mount('登记基础工资版本',`<p>${h(s.member.name)}</p>`+input('effectiveMonth','生效月份',month,'required type="month" min="1900-01" max="2199-12"')+amount('amount','参考月基础工资（元）',s.salary?.amount_cents??0)+area('note','变更原因（必填）')+'<p class="muted">按月份生效，保留此前全部版本。同一生效月登记新版本可纠正原记录。首版不自动计算月中入离职、请假扣款或个税。</p>',f=>api.payrollSave({requestKey:key,memberId,effectiveMonth:f.get('effectiveMonth'),amountCents:payrollCents(f.get('amount')),expectedLatestId:last?.id||null,note:f.get('note')},true),{kind:'attendance'},()=>api.payrollReceipt(key));return;}
  if(!s.salary||!s.attendanceValid)throw new ContractError('先设置生效基础工资，并完成来源一致的考勤月份核定。');const d=s.draft;
  mount(d?'修改工资草稿':'建立工资草稿',`<p>${h(s.member.name)} · ${h(month)}</p><p>本月参考基础工资：${h(payrollMoney(s.salary.amount_cents))}（${h(s.salary.effective_month)} 生效，第 ${s.salary.revision} 版）</p><p>引用考勤锁定第 ${s.closure.revision} 版。</p>${s.salaryChanged||s.attendanceChanged?'<p class="planning-rule">原草稿来源已变化。本次将引用最新版本，请重新核对每项金额；此前草稿仍保留。</p>':''}`+amount('base','本次基础工资（元，人工确认）',d?.base_cents??s.salary.amount_cents)+amount('bonus','奖金（元）',d?.bonus_cents??0)+amount('allowance','补贴（元）',d?.allowance_cents??0)+amount('adjustment','其他调整（元，可为负数）',d?.adjustment_cents??0)+area('note','金额依据与调整说明（必填）',d?.note||'')+'<label><input name="confirmed" type="checkbox" required>我已核对本次金额、考勤锁定版本和基础工资版本</label><p class="muted">基础工资只提供参考，月中入离职等情况需人工确认。合计仅为各项相加，不自动计算扣薪、绩效、社保或个税；保存草稿不会确认发薪或记账。</p>',f=>api.payrollSave({requestKey:key,memberId,month,expectedLatestId:d?.id||null,salaryId:s.salary.id,closureId:s.closure.id,baseCents:payrollCents(f.get('base')),bonusCents:payrollCents(f.get('bonus')),allowanceCents:payrollCents(f.get('allowance')),adjustmentCents:payrollCents(f.get('adjustment'),true),note:f.get('note'),confirmReviewed:f.get('confirmed')==='on'}),{kind:'attendance'},()=>api.payrollReceipt(key));
 }};
}
